mapper.select:
select r.id, r.create_time, r.update_time, r.mch_id, r.shop_id, r.member_id, r.order_id, r.order_no, r.sku_id, r.sku_name, r.spu_id, r.spu_name, r.spu_main_image, r.overall_rating, r.content, r.is_anonymous, r.nickname, r.avatar from s_product_sku_review r where r.deleted = 0 and r.spu_id = #{spuId}
and exists ( select 1 from s_product_sku_review_image i where i.deleted = 0 and i.review_id = r.id )
order by r.create_time desc
